class Solution {
public:
    int triangleNumber(vector<int>& nums) {
        int n=nums.size();
        sort(nums.begin(),nums.end());
        int cnt=0;
        for(int i=0;i<n-2;i++)
        {
            int k=i+2;
            for(int j=i+1;j<n-1 and nums[i];j++)
            {
                while(k<n and nums[i]+nums[j]>nums[k])
                    k++;
                cnt+=(k-j-1);
            }
        }
        return cnt;
    }
};

class Solution(object):
    def triangleNumber(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        nums.sort()
        ans = 0
        for i in range(n - 2):
            k = i
            for j in range(i + 1, n):
                while k + 1 < n and nums[i] + nums[j] > nums[k + 1]:
                    k += 1
                ans += max(0, k - j)
        return ans

